package org.humanjourney.core.geography.map;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.humanjourney.core.geography.map.client.*;
class BoundaryPresentationTest {
 final String dim=MapGeometryTest.DIM;final MapArea macro=MapGeometryTest.area(MapArea.Kind.MACRO,"macro",0,"",0,100),local=MapGeometryTest.area(MapArea.Kind.LOCAL,"local",0,"macro",0,20),far=MapGeometryTest.area(MapArea.Kind.LOCAL,"far",0,"",1000,20);
 final MapArea.Bounds view=new MapArea.Bounds(0,0,100,100);final MapSpatialIndex index=new MapSpatialIndex(MapGeometryTest.areas(macro,local,far));
 List<BoundaryPresentation.Layer> plan(BoundaryMode mode){return BoundaryPresentation.plan(index,dim,view,mode,index.hover(dim,5,5));}
 @Test void modeContractAndApprovedCycle(){var m=BoundaryMode.HOVER;for(String name:List.of("hover","locals","all","off")){assertEquals(name,m.id());assertTrue(BoundaryMode.valid(name));assertEquals(m,BoundaryMode.parse(name));m=m.next();}assertEquals(BoundaryMode.HOVER,m);assertEquals("HJ Borders: Hover",m.label());assertEquals("HJ Borders: All",BoundaryMode.ALL.label());assertFalse(BoundaryMode.valid("garbage"));assertFalse(BoundaryMode.valid(null));assertEquals(BoundaryMode.HOVER,BoundaryMode.parse("bad"));}
 @Test void hoverRendersOnlySelectedMacroThenLocal(){assertFalse(BoundaryMode.HOVER.locals());assertFalse(BoundaryMode.HOVER.macros());var p=plan(BoundaryMode.HOVER);assertEquals(List.of(macro,local),p.stream().map(BoundaryPresentation.Layer::area).toList());assertEquals(List.of(BoundaryPresentation.Style.HOVER_MACRO,BoundaryPresentation.Style.HOVER_LOCAL),p.stream().map(BoundaryPresentation.Layer::style).toList());}
 @Test void hoverWithoutSelectionRendersNothing(){assertTrue(BoundaryPresentation.plan(index,dim,view,BoundaryMode.HOVER,index.hover(dim,500,500)).isEmpty());assertTrue(BoundaryPresentation.plan(index,dim,view,BoundaryMode.HOVER,null).isEmpty());}
 @Test void localsUsesCulledLocalsThenSharedHighlights(){var p=plan(BoundaryMode.LOCALS);assertEquals(List.of(local,macro,local),p.stream().map(BoundaryPresentation.Layer::area).toList());assertEquals(BoundaryPresentation.Style.LOCAL,p.getFirst().style());assertFalse(p.stream().anyMatch(x->x.style()==BoundaryPresentation.Style.MACRO));assertFalse(p.stream().anyMatch(x->x.area().equals(far)));}
 @Test void allUsesApprovedLayerOrder(){var p=plan(BoundaryMode.ALL);assertEquals(List.of(BoundaryPresentation.Style.MACRO,BoundaryPresentation.Style.LOCAL,BoundaryPresentation.Style.HOVER_MACRO,BoundaryPresentation.Style.HOVER_LOCAL),p.stream().map(BoundaryPresentation.Layer::style).toList());}
 @Test void offHidesBoundariesButKeepsIndependentTooltipResult(){var hover=index.hover(dim,5,5);assertTrue(BoundaryPresentation.plan(index,dim,view,BoundaryMode.OFF,hover).isEmpty());assertTrue(hover.visible());assertEquals(local.label(),hover.primary());assertEquals(macro.label(),hover.secondary());}
 @Test void selectionExposesActualDiscoveredAreasAndKeys(){var hover=index.hover(dim,5,5);assertSame(local,hover.localArea());assertSame(macro,hover.macroArea());assertEquals(local.key(),hover.localKey());assertEquals(macro.key(),hover.macroKey());}
 @Test void undiscoveredHigherPriorityCannotAffectSelection(){var hidden=MapGeometryTest.area(MapArea.Kind.LOCAL,"hidden",99,"macro",0,20);assertEquals(local,index.hover(dim,5,5).localArea());var known=new MapSpatialIndex(MapGeometryTest.areas(macro,local,hidden));assertEquals(hidden,known.hover(dim,5,5).localArea());}
 @Test void independentMacroAndParentResolutionUnchanged(){var parent=MapGeometryTest.area(MapArea.Kind.MACRO,"parent",-1,"",200,10);var configured=MapGeometryTest.area(MapArea.Kind.LOCAL,"child",0,"parent",0,20);var i=new MapSpatialIndex(MapGeometryTest.areas(parent,macro,configured));assertEquals(parent,i.hover(dim,5,5).macroArea());var orphan=MapGeometryTest.area(MapArea.Kind.LOCAL,"child",0,"",0,20);assertEquals(macro,new MapSpatialIndex(MapGeometryTest.areas(macro,orphan)).hover(dim,5,5).macroArea());}
 @Test void macroOnlyAndLocalOnlyHighlightsAreValid(){var onlyMacro=new MapSpatialIndex(MapGeometryTest.areas(macro));assertEquals(List.of(macro),BoundaryPresentation.plan(onlyMacro,dim,view,BoundaryMode.HOVER,onlyMacro.hover(dim,5,5)).stream().map(BoundaryPresentation.Layer::area).toList());var standalone=MapGeometryTest.area(MapArea.Kind.LOCAL,"alone",0,"",0,20);var onlyLocal=new MapSpatialIndex(MapGeometryTest.areas(standalone));assertEquals(List.of(standalone),BoundaryPresentation.plan(onlyLocal,dim,view,BoundaryMode.HOVER,onlyLocal.hover(dim,5,5)).stream().map(BoundaryPresentation.Layer::area).toList());}
 @Test void ambiguousLocalHasNoSelectedGeometry(){var tied=MapGeometryTest.area(MapArea.Kind.LOCAL,"tie",0,"macro",0,20);var i=new MapSpatialIndex(MapGeometryTest.areas(local,tied,macro));var hover=i.hover(dim,5,5);assertTrue(hover.ambiguous());assertNull(hover.localKey());assertNull(hover.localArea());assertEquals(macro,hover.macroArea());}
 @Test void wrongDimensionAndOutOfViewRenderNothing(){assertTrue(BoundaryPresentation.plan(index,"minecraft:the_nether",view,BoundaryMode.ALL,index.hover(dim,5,5)).isEmpty());assertTrue(BoundaryPresentation.plan(index,dim,new MapArea.Bounds(500,500,600,600),BoundaryMode.ALL,index.hover(dim,5,5)).isEmpty());}
 @Test void staleSelectionCannotGuessAnotherGeometry(){var old=MapGeometryTest.area(MapArea.Kind.LOCAL,"local",0,"",300,10);var hover=new MapSpatialIndex(MapGeometryTest.areas(old)).hover(dim,305,5);assertTrue(BoundaryPresentation.plan(index,dim,view,BoundaryMode.HOVER,hover).isEmpty());}
 @Test void persistentLocalPriorityStillDrawsSpecificLast(){var high=MapGeometryTest.area(MapArea.Kind.LOCAL,"high",10,"macro",0,10);var i=new MapSpatialIndex(MapGeometryTest.areas(local,high));var layers=BoundaryPresentation.plan(i,dim,view,BoundaryMode.LOCALS,null);assertEquals(List.of(local,high),layers.stream().map(BoundaryPresentation.Layer::area).toList());}
 @Test void stylesCommunicateLayerNotRegionIdentity(){assertEquals(0xD6E6CE,BoundaryPresentation.Style.LOCAL.rgb);assertEquals(0x7EA8D8,BoundaryPresentation.Style.MACRO.rgb);assertEquals(0xFFFFFF,BoundaryPresentation.Style.HOVER_LOCAL.rgb);assertEquals(0x7FC3FF,BoundaryPresentation.Style.HOVER_MACRO.rgb);}
}
